static bool onSegment(double *p, double *a, double *b) {
  double cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]);
  if (fabs(cross) > 1e-9) return false;
  return p[0] >= fmin(a[0], b[0]) - 1e-9 && p[0] <= fmax(a[0], b[0]) + 1e-9 &&
         p[1] >= fmin(a[1], b[1]) - 1e-9 && p[1] <= fmax(a[1], b[1]) + 1e-9;
}

double *intersection(int *start1, int *end1, int *start2, int *end2, int *returnSize) {
  double x1 = start1[0], y1 = start1[1], x2 = end1[0], y2 = end1[1];
  double x3 = start2[0], y3 = start2[1], x4 = end2[0], y4 = end2[1];
  double d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  *returnSize = 0;
  if (fabs(d) > 1e-12) {
    double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
    double u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d;
    if (t >= -1e-9 && t <= 1 + 1e-9 && u >= -1e-9 && u <= 1 + 1e-9) {
      double *res = (double *)malloc(sizeof(double) * 2);
      res[0] = x1 + t * (x2 - x1);
      res[1] = y1 + t * (y2 - y1);
      *returnSize = 2;
      return res;
    }
    return NULL;
  }
  double a1[2] = {x1, y1}, b1[2] = {x2, y2}, a2[2] = {x3, y3}, b2[2] = {x4, y4};
  double candidates[4][2];
  int n = 0;
  if (onSegment(a1, a2, b2)) {
    candidates[n][0] = a1[0];
    candidates[n][1] = a1[1];
    n++;
  }
  if (onSegment(b1, a2, b2)) {
    candidates[n][0] = b1[0];
    candidates[n][1] = b1[1];
    n++;
  }
  if (onSegment(a2, a1, b1)) {
    candidates[n][0] = a2[0];
    candidates[n][1] = a2[1];
    n++;
  }
  if (onSegment(b2, a1, b1)) {
    candidates[n][0] = b2[0];
    candidates[n][1] = b2[1];
    n++;
  }
  if (n == 0) return NULL;
  int best = 0;
  for (int i = 1; i < n; i++) {
    if (candidates[i][0] < candidates[best][0] ||
        (candidates[i][0] == candidates[best][0] && candidates[i][1] < candidates[best][1])) {
      best = i;
    }
  }
  double *res = (double *)malloc(sizeof(double) * 2);
  res[0] = candidates[best][0];
  res[1] = candidates[best][1];
  *returnSize = 2;
  return res;
}

class Solution {
  bool onSegment(vector<int> &p, vector<int> &a, vector<int> &b) {
    double cross = (double)(b[0] - a[0]) * (p[1] - a[1]) - (double)(b[1] - a[1]) * (p[0] - a[0]);
    if (fabs(cross) > 1e-9) return false;
    return p[0] >= min(a[0], b[0]) && p[0] <= max(a[0], b[0]) && p[1] >= min(a[1], b[1]) &&
           p[1] <= max(a[1], b[1]);
  }

public:
  vector<double> intersection(vector<int> &start1, vector<int> &end1, vector<int> &start2, vector<int> &end2) {
    double x1 = start1[0], y1 = start1[1], x2 = end1[0], y2 = end1[1];
    double x3 = start2[0], y3 = start2[1], x4 = end2[0], y4 = end2[1];
    double d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
    if (fabs(d) > 1e-12) {
      double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
      double u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d;
      if (t >= -1e-9 && t <= 1 + 1e-9 && u >= -1e-9 && u <= 1 + 1e-9) {
        return {x1 + t * (x2 - x1), y1 + t * (y2 - y1)};
      }
      return {};
    }
    vector<vector<int>> candidates;
    if (onSegment(start1, start2, end2)) candidates.push_back(start1);
    if (onSegment(end1, start2, end2)) candidates.push_back(end1);
    if (onSegment(start2, start1, end1)) candidates.push_back(start2);
    if (onSegment(end2, start1, end1)) candidates.push_back(end2);
    if (candidates.empty()) return {};
    sort(candidates.begin(), candidates.end());
    return {(double)candidates[0][0], (double)candidates[0][1]};
  }
};

func onSegment(p, a, b []int) bool {
	cross := float64(b[0]-a[0])*float64(p[1]-a[1]) - float64(b[1]-a[1])*float64(p[0]-a[0])
	if math.Abs(cross) > 1e-9 {
		return false
	}
	return p[0] >= min(a[0], b[0]) && p[0] <= max(a[0], b[0]) && p[1] >= min(a[1], b[1]) && p[1] <= max(a[1], b[1])
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func intersection(start1 []int, end1 []int, start2 []int, end2 []int) []float64 {
	x1, y1 := float64(start1[0]), float64(start1[1])
	x2, y2 := float64(end1[0]), float64(end1[1])
	x3, y3 := float64(start2[0]), float64(start2[1])
	x4, y4 := float64(end2[0]), float64(end2[1])
	d := (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4)
	if math.Abs(d) > 1e-12 {
		t := ((x1-x3)*(y3-y4) - (y1-y3)*(x3-x4)) / d
		u := ((x1-x3)*(y1-y2) - (y1-y3)*(x1-x2)) / d
		if t >= -1e-9 && t <= 1+1e-9 && u >= -1e-9 && u <= 1+1e-9 {
			return []float64{x1 + t*(x2-x1), y1 + t*(y2-y1)}
		}
		return []float64{}
	}
	var candidates [][]int
	if onSegment(start1, start2, end2) {
		candidates = append(candidates, start1)
	}
	if onSegment(end1, start2, end2) {
		candidates = append(candidates, end1)
	}
	if onSegment(start2, start1, end1) {
		candidates = append(candidates, start2)
	}
	if onSegment(end2, start1, end1) {
		candidates = append(candidates, end2)
	}
	if len(candidates) == 0 {
		return []float64{}
	}
	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i][0] != candidates[j][0] {
			return candidates[i][0] < candidates[j][0]
		}
		return candidates[i][1] < candidates[j][1]
	})
	return []float64{float64(candidates[0][0]), float64(candidates[0][1])}
}

class Solution {
  private boolean onSegment(int[] p, int[] a, int[] b) {
    double cross = (double) (b[0] - a[0]) * (p[1] - a[1]) - (double) (b[1] - a[1]) * (p[0] - a[0]);
    if (Math.abs(cross) > 1e-9) return false;
    return p[0] >= Math.min(a[0], b[0]) && p[0] <= Math.max(a[0], b[0]) && p[1] >= Math.min(a[1], b[1])
        && p[1] <= Math.max(a[1], b[1]);
  }

  public double[] intersection(int[] start1, int[] end1, int[] start2, int[] end2) {
    double x1 = start1[0], y1 = start1[1], x2 = end1[0], y2 = end1[1];
    double x3 = start2[0], y3 = start2[1], x4 = end2[0], y4 = end2[1];
    double d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
    if (Math.abs(d) > 1e-12) {
      double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
      double u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d;
      if (t >= -1e-9 && t <= 1 + 1e-9 && u >= -1e-9 && u <= 1 + 1e-9) {
        return new double[] { x1 + t * (x2 - x1), y1 + t * (y2 - y1) };
      }
      return new double[0];
    }
    List<int[]> candidates = new ArrayList<>();
    if (onSegment(start1, start2, end2)) candidates.add(start1);
    if (onSegment(end1, start2, end2)) candidates.add(end1);
    if (onSegment(start2, start1, end1)) candidates.add(start2);
    if (onSegment(end2, start1, end1)) candidates.add(end2);
    if (candidates.isEmpty()) return new double[0];
    candidates.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
    return new double[] { candidates.get(0)[0], candidates.get(0)[1] };
  }
}

class Solution:
    def intersection(self, start1: List[int], end1: List[int], start2: List[int], end2: List[int]) -> List[float]:
        x1, y1 = start1
        x2, y2 = end1
        x3, y3 = start2
        x4, y4 = end2
        d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
        if abs(d) > 1e-12:
            t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d
            u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d
            if -1e-9 <= t <= 1 + 1e-9 and -1e-9 <= u <= 1 + 1e-9:
                return [x1 + t * (x2 - x1), y1 + t * (y2 - y1)]
            return []

        def on_segment(p, a, b):
            cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])
            if abs(cross) > 1e-9:
                return False
            return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

        candidates = []
        for p in (start1, end1):
            if on_segment(p, start2, end2):
                candidates.append(p)
        for p in (start2, end2):
            if on_segment(p, start1, end1):
                candidates.append(p)
        if not candidates:
            return []
        candidates.sort()
        return [float(candidates[0][0]), float(candidates[0][1])]

impl Solution {
  pub fn intersection(start1: Vec<i32>, end1: Vec<i32>, start2: Vec<i32>, end2: Vec<i32>) -> Vec<f64> {
    let (x1, y1) = (start1[0] as f64, start1[1] as f64);
    let (x2, y2) = (end1[0] as f64, end1[1] as f64);
    let (x3, y3) = (start2[0] as f64, start2[1] as f64);
    let (x4, y4) = (end2[0] as f64, end2[1] as f64);
    let d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
    if d.abs() > 1e-12 {
      let t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
      let u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d;
      if t >= -1e-9 && t <= 1.0 + 1e-9 && u >= -1e-9 && u <= 1.0 + 1e-9 {
        return vec![x1 + t * (x2 - x1), y1 + t * (y2 - y1)];
      }
      return vec![];
    }
    fn on_segment(p: &[i32], a: &[i32], b: &[i32]) -> bool {
      let cross = (b[0] - a[0]) as f64 * (p[1] - a[1]) as f64
        - (b[1] - a[1]) as f64 * (p[0] - a[0]) as f64;
      if cross.abs() > 1e-9 {
        return false;
      }
      p[0] >= a[0].min(b[0])
        && p[0] <= a[0].max(b[0])
        && p[1] >= a[1].min(b[1])
        && p[1] <= a[1].max(b[1])
    }
    let mut candidates: Vec<Vec<i32>> = vec![];
    for p in [&start1, &end1] {
      if on_segment(p, &start2, &end2) {
        candidates.push(p.clone());
      }
    }
    for p in [&start2, &end2] {
      if on_segment(p, &start1, &end1) {
        candidates.push(p.clone());
      }
    }
    if candidates.is_empty() {
      return vec![];
    }
    candidates.sort();
    vec![candidates[0][0] as f64, candidates[0][1] as f64]
  }
}

const intersection = (start1: number[], end1: number[], start2: number[], end2: number[]): number[] => {
  const [x1, y1] = start1;
  const [x2, y2] = end1;
  const [x3, y3] = start2;
  const [x4, y4] = end2;
  const d = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (Math.abs(d) > 1e-12) {
    const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / d;
    const u = ((x1 - x3) * (y1 - y2) - (y1 - y3) * (x1 - x2)) / d;
    if (t >= -1e-9 && t <= 1 + 1e-9 && u >= -1e-9 && u <= 1 + 1e-9) {
      return [x1 + t * (x2 - x1), y1 + t * (y2 - y1)];
    }
    return [];
  }
  const onSegment = (p: number[], a: number[], b: number[]): boolean => {
    const cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]);
    if (Math.abs(cross) > 1e-9) return false;
    return (
      Math.min(a[0], b[0]) <= p[0] &&
      p[0] <= Math.max(a[0], b[0]) &&
      Math.min(a[1], b[1]) <= p[1] &&
      p[1] <= Math.max(a[1], b[1])
    );
  };
  const candidates: number[][] = [];
  for (const p of [start1, end1]) if (onSegment(p, start2, end2)) candidates.push(p);
  for (const p of [start2, end2]) if (onSegment(p, start1, end1)) candidates.push(p);
  if (candidates.length === 0) return [];
  candidates.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  return [candidates[0][0], candidates[0][1]];
};
